package com.vovanthinh.controller;
import java.io.IOException;import java.math.BigDecimal;import jakarta.servlet.*;import jakarta.servlet.annotation.MultipartConfig;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import com.vovanthinh.model.Product;import com.vovanthinh.service.ProductService;import com.vovanthinh.service.CategoryService;import com.vovanthinh.service.impl.ProductServiceImpl;import com.vovanthinh.service.impl.CategoryServiceImpl;import com.vovanthinh.util.FileUploadUtil;
@WebServlet("/admin/product/edit") @MultipartConfig(maxFileSize=5*1024*1024,maxRequestSize=6*1024*1024) public class ProductEditController extends HttpServlet{private final ProductService ps=new ProductServiceImpl();private final CategoryService cs=new CategoryServiceImpl();
 protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{Product p=ps.get(Integer.parseInt(r.getParameter("id")));if(p==null){s.sendError(404);return;}r.setAttribute("product",p);r.setAttribute("categories",cs.getAll());r.getRequestDispatcher("/admin/product-edit.jsp").forward(r,s);}catch(Exception e){s.sendError(400);}}
 protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{r.setCharacterEncoding("UTF-8");try{int id=Integer.parseInt(r.getParameter("productId"));Product p=ps.get(id);if(p==null){s.sendError(404);return;}p.setProductName(r.getParameter("productName"));p.setBrand(r.getParameter("brand"));p.setPrice(new BigDecimal(r.getParameter("price")));p.setQuantity(Integer.parseInt(r.getParameter("quantity")));p.setDescription(r.getParameter("description"));String cid=r.getParameter("categoryId");p.setCategory(cid==null||cid.isBlank()?null:cs.get(Integer.parseInt(cid)));Part part=r.getPart("image");if(part!=null&&part.getSize()>0)p.setImage(FileUploadUtil.saveImage(r.getServletContext(),part));ps.update(p);s.sendRedirect(r.getContextPath()+"/admin/product/list");}catch(Exception e){e.printStackTrace();r.setAttribute("error","Không thể cập nhật sản phẩm: "+e.getMessage());r.setAttribute("categories",cs.getAll());r.getRequestDispatcher("/admin/product-edit.jsp").forward(r,s);}}}
